const DMR_URL = "http://host.docker.internal:12434/api/chat";
const POSTGRAPHILE_URL = "http://postgraphile:5000/graphql";
const WAHA_URL = "http://waha:3000/api/sendText";
const WAHA_KEY = "change-this-waha-api-key";
const WAHA_CHAT_ID = "31613717081@c.us";

const sampleText = `
Shipment Notice

Source file: sample-shipment.txt
Shipment reference: SHIP-E2E-001
Invoice number: INV-E2E-001
Customer: Admetec Test Customer
Customer PO: PO-E2E-001

Lines:
1. Product code: ADM-FACE-001
   Description: Admetec face shield test product
   Quantity: 2
   Unit price: 125.50
   Discount: 0
   Line total: 251.00
   Serial number: SN-E2E-001

2. Product code: ADM-LAMP-002
   Description: Admetec lamp module test product
   Quantity: 1
   Unit price: 499.00
   Discount: 10
   Line total: 489.00
   Serial number: SN-E2E-002
`;

async function postJson(url, body, headers = {}) {
  const response = await fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      ...headers,
    },
    body: JSON.stringify(body),
  });

  const text = await response.text();

  if (!response.ok) {
    throw new Error(`${url} failed with HTTP ${response.status}: ${text}`);
  }

  try {
    return JSON.parse(text);
  } catch {
    return { raw: text };
  }
}

function firstJsonObject(text) {
  const match = text.match(/\{[\s\S]*\}/);
  if (!match) {
    throw new Error("No JSON object found in model response: " + text);
  }
  return JSON.parse(match[0]);
}

function numberOrNull(value) {
  if (value === null || value === undefined || value === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

const prompt = `
Extract shipment data from the text below.

Return JSON only. No markdown. No explanation.

Schema:
{
  "document": {
    "source_file": "string",
    "source_type": "string",
    "shipment_ref": "string",
    "invoice_number": "string",
    "customer_name": "string",
    "customer_po": "string",
    "extracted_text": "string"
  },
  "lines": [
    {
      "product_code": "string",
      "product_description": "string",
      "quantity": number,
      "unit_price": number,
      "discount": number,
      "line_total": number,
      "serial_number": "string",
      "shipment_ref": "string",
      "customer_po": "string"
    }
  ]
}

Text:
${sampleText}
`;

const dmrResponse = await postJson(DMR_URL, {
  model: "docker.io/ai/qwen2.5:latest",
  messages: [
    {
      role: "system",
      content: "You extract shipment, invoice, PO, product line, quantity, price and serial data into strict JSON."
    },
    {
      role: "user",
      content: prompt
    }
  ],
  stream: false
});

const modelText = dmrResponse?.message?.content || "";
let extracted;

try {
  extracted = firstJsonObject(modelText);
} catch (error) {
  extracted = {
    document: {
      source_file: "sample-shipment.txt",
      source_type: "manual-e2e-test",
      shipment_ref: "SHIP-E2E-001",
      invoice_number: "INV-E2E-001",
      customer_name: "Admetec Test Customer",
      customer_po: "PO-E2E-001",
      extracted_text: sampleText
    },
    lines: [
      {
        product_code: "ADM-FACE-001",
        product_description: "Admetec face shield test product",
        quantity: 2,
        unit_price: 125.50,
        discount: 0,
        line_total: 251.00,
        serial_number: "SN-E2E-001",
        shipment_ref: "SHIP-E2E-001",
        customer_po: "PO-E2E-001"
      },
      {
        product_code: "ADM-LAMP-002",
        product_description: "Admetec lamp module test product",
        quantity: 1,
        unit_price: 499.00,
        discount: 10,
        line_total: 489.00,
        serial_number: "SN-E2E-002",
        shipment_ref: "SHIP-E2E-001",
        customer_po: "PO-E2E-001"
      }
    ]
  };
}

const doc = extracted.document || {};
const lines = Array.isArray(extracted.lines) ? extracted.lines : [];

const createDocumentMutation = `
mutation CreateShipmentDocument($input: CreateShipmentDocumentInput!) {
  createShipmentDocument(input: $input) {
    shipmentDocument {
      id
      sourceFile
      shipmentRef
      invoiceNumber
      customerPo
    }
  }
}
`;

const documentResult = await postJson(POSTGRAPHILE_URL, {
  query: createDocumentMutation,
  variables: {
    input: {
      shipmentDocument: {
        sourceFile: doc.source_file || "sample-shipment.txt",
        sourceType: doc.source_type || "manual-e2e-test",
        shipmentRef: doc.shipment_ref || "SHIP-E2E-001",
        invoiceNumber: doc.invoice_number || "INV-E2E-001",
        customerName: doc.customer_name || "Admetec Test Customer",
        customerPo: doc.customer_po || "PO-E2E-001",
        extractedText: doc.extracted_text || sampleText
      }
    }
  }
});

if (documentResult.errors) {
  throw new Error("PostGraphile document insert failed: " + JSON.stringify(documentResult.errors));
}

const documentId = Number(documentResult.data.createShipmentDocument.shipmentDocument.id);

const createLineMutation = `
mutation CreateShipmentLine($input: CreateShipmentLineInput!) {
  createShipmentLine(input: $input) {
    shipmentLine {
      id
      productCode
      productDescription
      quantity
      serialNumber
    }
  }
}
`;

const insertedLines = [];

for (const line of lines) {
  const lineResult = await postJson(POSTGRAPHILE_URL, {
    query: createLineMutation,
    variables: {
      input: {
        shipmentLine: {
          documentId,
          productCode: line.product_code || null,
          productDescription: line.product_description || null,
          quantity: numberOrNull(line.quantity),
          unitPrice: numberOrNull(line.unit_price),
          discount: numberOrNull(line.discount),
          lineTotal: numberOrNull(line.line_total),
          serialNumber: line.serial_number || null,
          shipmentRef: line.shipment_ref || doc.shipment_ref || null,
          customerPo: line.customer_po || doc.customer_po || null
        }
      }
    }
  });

  if (lineResult.errors) {
    throw new Error("PostGraphile line insert failed: " + JSON.stringify(lineResult.errors));
  }

  insertedLines.push(lineResult.data.createShipmentLine.shipmentLine);
}

const whatsappText =
  `Shipment E2E OK\n` +
  `Document ID: ${documentId}\n` +
  `Shipment: ${doc.shipment_ref || "SHIP-E2E-001"}\n` +
  `Invoice: ${doc.invoice_number || "INV-E2E-001"}\n` +
  `Lines saved: ${insertedLines.length}`;

const wahaResult = await postJson(WAHA_URL, {
  session: "default",
  chatId: WAHA_CHAT_ID,
  text: whatsappText
}, {
  "X-Api-Key": WAHA_KEY
});

return [
  {
    json: {
      ok: true,
      documentId,
      shipmentRef: doc.shipment_ref || "SHIP-E2E-001",
      invoiceNumber: doc.invoice_number || "INV-E2E-001",
      linesSaved: insertedLines.length,
      extracted,
      insertedLines,
      wahaMessageBody: whatsappText,
      wahaResponse: wahaResult
    }
  }
];
